css:
.slash{position:absolute;width:180px;height:1px;background:#3b3a35;transform:rotate(-45deg);z-index:0}
.slash:nth-child(2){background:#b9ad86;width:140px}
.slash:nth-child(3){background:#c46a5a;width:96px}
/* 接線＋星 */
.ph-wrap::before{content:"";position:absolute;right:-6%;top:12%;width:110px;height:1px;background:#c9ad6a;rotate:-38deg}
.spark::after{content:"✦";color:#c9ad6a;font-size:11px;position:absolute;left:8%;bottom:6%}
/* 手描き線画 */
.doodle{position:absolute;stroke:#222;stroke-width:1;fill:none;vector-effect:non-scaling-stroke}
.doodle.swing{left:6%;bottom:8%;width:14%}
.doodle.gym{right:8%;top:12%;width:18%}
